// ==========================================================================
// HU-04 · Validar y parsear la consulta en lenguaje natural
// Entrada : salida del Webhook (headers, params, query, body)
// Salida  : objeto normalizado o lista de errores de validacion
// ==========================================================================

const entrada = $input.first().json;
const body = entrada.body ?? {};

const PARAMETROS_VALIDOS = ['pm25', 'pm10', 'no2', 'so2', 'o3', 'co'];

const pregunta = String(body.pregunta ?? '').trim();
const ciudad = String(body.ciudad ?? 'Lima').trim();
const parametro = String(body.parametro ?? 'pm25').trim().toLowerCase();

const errores = [];

if (!pregunta) {
  errores.push('El campo "pregunta" es obligatorio.');
} else if (pregunta.length < 5) {
  errores.push('La pregunta es demasiado corta (minimo 5 caracteres).');
} else if (pregunta.length > 500) {
  errores.push('La pregunta excede los 500 caracteres permitidos.');
}

if (!PARAMETROS_VALIDOS.includes(parametro)) {
  errores.push('Parametro no soportado: ' + parametro + '. Validos: ' + PARAMETROS_VALIDOS.join(', ') + '.');
}

if (errores.length > 0) {
  return [{
    json: {
      ok: false,
      codigo_http: 400,
      errores,
      procesado_en: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    ok: true,
    codigo_http: 200,
    consulta: { pregunta, ciudad, parametro },
    // Sprint 1: aqui se conectaran PostgreSQL (historico) y el AI Agent
    etapa: 'sprint-0-esqueleto',
    procesado_en: new Date().toISOString()
  }
}];
